package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                          // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)   // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0                                // PIC 99 len=2 = 0
var WsCount int64 = 0                               // PIC 99 len=2 = 0
var WsBalEd string = ""                             // PIC ZZ,ZZZ,ZZ9.99 len=13

var schedRec SchedRec
var schedFile *os.File
var schedScanner *bufio.Scanner

func parseImpliedDecimal(s string, scale int32) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(trimmed)
	if err != nil {
		fmt.Fprintf(os.Stderr, "invalid decimal field %q: %v\n", s, err)
		os.Exit(1)
	}
	return d.Shift(-scale)
}

func parseImpliedInt(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	v, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		fmt.Fprintf(os.Stderr, "invalid integer field %q: %v\n", s, err)
		os.Exit(1)
	}
	return v
}

func truncHighOrder(d decimal.Decimal, intDigits int) decimal.Decimal {
	if intDigits <= 0 {
		return d
	}
	neg := d.IsNegative()
	abs := d.Abs()
	intPart := abs.Truncate(0)
	frac := abs.Sub(intPart)
	intStr := intPart.String()
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	intDec, _ := decimal.NewFromString(intStr)
	resultAbs := intDec.Add(frac)
	if neg {
		return resultAbs.Neg()
	}
	return resultAbs
}

func formatWsBalEd(val decimal.Decimal) string {
	isNeg := val.IsNegative()
	abs := val.Abs()

	intPart := abs.Truncate(0)
	intStrRaw := intPart.String()
	if len(intStrRaw) > 8 {
		intStrRaw = intStrRaw[len(intStrRaw)-8:]
	}
	intStrPadded := strings.Repeat("0", 8-len(intStrRaw)) + intStrRaw
	digits := []byte(intStrPadded)

	pic := []byte{'Z', 'Z', ',', 'Z', 'Z', 'Z', ',', 'Z', 'Z', '9'}
	digitMap := []int{0, 1, -1, 2, 3, 4, -1, 5, 6, 7}
	res := make([]byte, 10)
	suppression := true
	for i, p := range pic {
		di := digitMap[i]
		if p == ',' {
			if suppression {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		} else if p == 'Z' {
			d := digits[di]
			if suppression && d == '0' {
				res[i] = ' '
			} else if suppression && d != '0' {
				suppression = false
				res[i] = d
			} else {
				res[i] = d
			}
		} else { // '9'
			d := digits[di]
			res[i] = d
		}
	}

	frac := abs.Sub(intPart)
	fracShift := frac.Shift(2).Truncate(0)
	fracInt := fracShift.IntPart()
	fracStr := fmt.Sprintf("%02d", fracInt)

	result := string(res) + "." + fracStr
	if isNeg {
		if len(result) > 0 && result[0] == ' ' {
			result = "-" + result[1:]
		} else {
			result = "-" + result
		}
	}
	return result
}

func formatPic99(n int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	if n < 0 {
		n = -n
	}
	n = n % mod
	return fmt.Sprintf("%0*d", width, n)
}

// READ-PARA
func ReadPara() {
	if schedScanner.Scan() {
		line := schedScanner.Text()
		if len(line) < 16 {
			line = line + strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		schedRec.ScAcct = line[0:4]
		schedRec.ScPrin = parseImpliedDecimal(line[4:11], 2)
		schedRec.ScRate = parseImpliedDecimal(line[11:15], 2)
		schedRec.ScYears = parseImpliedInt(line[15:16])
	} else {
		if err := schedScanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

// PROCESS-PARA
func ProcessPara() {
	WsBal = schedRec.ScPrin
	WsBal = truncHighOrder(WsBal, 8)
	WsYear = 1
	for !(WsYear > schedRec.ScYears) {
		rateDiv100 := schedRec.ScRate.Shift(-2)
		factor := decimal.NewFromInt(1).Add(rateDiv100)
		raw := WsBal.Mul(factor)
		rounded := raw.Round(2)
		WsBal = truncHighOrder(rounded, 8)
		WsBalEd = formatWsBalEd(WsBal)
		yearStr := formatPic99(WsYear, 2)
		line := schedRec.ScAcct + " Y" + yearStr + " " + WsBalEd
		fmt.Println(line)
		WsYear++
	}
	WsBalEd = formatWsBalEd(WsBal)
	line2 := schedRec.ScAcct + " FINAL " + WsBalEd
	fmt.Println(line2)
	WsCount++
	WsCount = WsCount % 100
	ReadPara()
}

// MAIN-PARA
func MainPara() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer schedFile.Close()
	schedScanner = bufio.NewScanner(schedFile)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	countStr := formatPic99(WsCount, 2)
	fmt.Println("SCHEDULES: " + countStr)
}

func main() {
	MainPara()
}
